CREATE ROLE ecclesia_app NOLOGIN NOSUPERUSER NOBYPASSRLS;
CREATE TABLE networks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE regions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), network_id uuid NOT NULL REFERENCES networks, name text NOT NULL);
CREATE TABLE churches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), network_id uuid NOT NULL REFERENCES networks, region_id uuid REFERENCES regions, name text NOT NULL, primary_color text NOT NULL DEFAULT '#7062db', plan text NOT NULL DEFAULT 'rede', modules text[] NOT NULL DEFAULT ARRAY['people','cells','finance'], affiliated_on date NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE campuses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, name text NOT NULL, UNIQUE(church_id,id));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, totp_secret text, person_id uuid);
CREATE TABLE memberships(user_id uuid REFERENCES users, church_id uuid REFERENCES churches, role text NOT NULL CHECK(role IN ('admin','secretary','treasurer','leader','member')), campus_id uuid, PRIMARY KEY(user_id,church_id), FOREIGN KEY(church_id,campus_id) REFERENCES campuses(church_id,id));
CREATE TABLE network_members(user_id uuid REFERENCES users, network_id uuid REFERENCES networks, PRIMARY KEY(user_id,network_id));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL, mfa boolean NOT NULL DEFAULT false);
CREATE TABLE login_challenges(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0);
CREATE TABLE access_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, user_id uuid NOT NULL REFERENCES users, scope text NOT NULL CHECK(scope IN ('people','finance','cells')), expires_at timestamptz NOT NULL, revoked_at timestamptz, granted_by uuid NOT NULL REFERENCES users);
CREATE TABLE audit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid REFERENCES churches, actor_id uuid REFERENCES users, action text NOT NULL, resource_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION actor_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.actor',true),'')::uuid $$;
CREATE FUNCTION tenant_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.church',true),'')::uuid $$;
CREATE FUNCTION local_role() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT role FROM memberships WHERE user_id=actor_id() AND church_id=tenant_id() $$;
CREATE FUNCTION can_access(scope text, writing boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT COALESCE((SELECT CASE WHEN role='admin' THEN true WHEN scope='people' THEN role='secretary' WHEN scope='cells' THEN role IN ('leader','secretary') WHEN scope='finance' THEN role='treasurer' WHEN scope='pastoral' THEN false ELSE false END FROM memberships WHERE user_id=actor_id() AND church_id=tenant_id()),false)
 OR (NOT writing AND scope <> 'pastoral' AND EXISTS(SELECT 1 FROM access_grants g JOIN churches c ON c.id=g.church_id JOIN network_members n ON n.network_id=c.network_id AND n.user_id=g.user_id WHERE g.church_id=tenant_id() AND g.user_id=actor_id() AND g.scope=can_access.scope AND g.revoked_at IS NULL AND g.expires_at>now()))
$$;
CREATE TABLE households(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, name text NOT NULL, UNIQUE(church_id,id));
CREATE TABLE people(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, campus_id uuid, household_id uuid, user_id uuid REFERENCES users, name text NOT NULL, email text, phone text, status text NOT NULL DEFAULT 'member' CHECK(status IN ('visitor','member','worker','inactive')), custom_fields jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(church_id,id), FOREIGN KEY(church_id,campus_id) REFERENCES campuses(church_id,id), FOREIGN KEY(church_id,household_id) REFERENCES households(church_id,id));
CREATE TABLE leadership_terms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, person_id uuid NOT NULL, title text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, CHECK(ends_on>=starts_on), FOREIGN KEY(church_id,person_id) REFERENCES people(church_id,id));
CREATE TABLE credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, person_id uuid NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, FOREIGN KEY(church_id,person_id) REFERENCES people(church_id,id));
CREATE TABLE transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_church_id uuid NOT NULL REFERENCES churches, target_church_id uuid NOT NULL REFERENCES churches, person_id uuid NOT NULL REFERENCES people, requested_by uuid NOT NULL REFERENCES users, accepted_by uuid REFERENCES users, status text NOT NULL DEFAULT 'pending', CHECK(source_church_id<>target_church_id));
CREATE TABLE cells(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, campus_id uuid, name text NOT NULL, leader_name text NOT NULL, parent_id uuid, weekday int NOT NULL DEFAULT 3 CHECK(weekday BETWEEN 0 AND 6), UNIQUE(church_id,id), FOREIGN KEY(church_id,parent_id) REFERENCES cells(church_id,id), FOREIGN KEY(church_id,campus_id) REFERENCES campuses(church_id,id));
CREATE TABLE cell_members(church_id uuid NOT NULL REFERENCES churches, cell_id uuid NOT NULL, person_id uuid NOT NULL, PRIMARY KEY(cell_id,person_id), FOREIGN KEY(church_id,cell_id) REFERENCES cells(church_id,id), FOREIGN KEY(church_id,person_id) REFERENCES people(church_id,id));
CREATE TABLE meetings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, cell_id uuid NOT NULL, held_on date NOT NULL, visitors int NOT NULL DEFAULT 0 CHECK(visitors>=0), UNIQUE(cell_id,held_on), UNIQUE(church_id,id), FOREIGN KEY(church_id,cell_id) REFERENCES cells(church_id,id));
CREATE TABLE attendance(church_id uuid NOT NULL REFERENCES churches, meeting_id uuid NOT NULL, person_id uuid NOT NULL, present boolean NOT NULL, PRIMARY KEY(meeting_id,person_id), FOREIGN KEY(church_id,meeting_id) REFERENCES meetings(church_id,id), FOREIGN KEY(church_id,person_id) REFERENCES people(church_id,id));
CREATE TABLE workflow_cards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, person_id uuid NOT NULL, stage int NOT NULL DEFAULT 0 CHECK(stage BETWEEN 0 AND 3), FOREIGN KEY(church_id,person_id) REFERENCES people(church_id,id));
CREATE TABLE schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, user_id uuid NOT NULL REFERENCES users, ministry text NOT NULL, starts_at timestamptz NOT NULL, response text NOT NULL DEFAULT 'pending' CHECK(response IN ('pending','accepted','declined')));
CREATE TABLE pastoral_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, person_id uuid NOT NULL, author_id uuid NOT NULL REFERENCES users, ciphertext text NOT NULL, FOREIGN KEY(church_id,person_id) REFERENCES people(church_id,id));
CREATE TABLE prayer_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, user_id uuid NOT NULL REFERENCES users, confidential boolean NOT NULL, ciphertext text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE privacy_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, user_id uuid NOT NULL REFERENCES users, kind text NOT NULL CHECK(kind IN ('access','correction','deletion')), detail text NOT NULL, status text NOT NULL DEFAULT 'received', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, code text NOT NULL, name text NOT NULL, kind text NOT NULL CHECK(kind IN ('asset','income','expense','liability')), UNIQUE(church_id,id), UNIQUE(church_id,code));
CREATE TABLE funds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, name text NOT NULL, UNIQUE(church_id,id));
CREATE TABLE cost_centers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, name text NOT NULL, UNIQUE(church_id,id));
CREATE TABLE financial_closings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, through_date date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE journal_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, occurred_on date NOT NULL DEFAULT CURRENT_DATE, description text NOT NULL, fund_id uuid, cost_center_id uuid, reversal_of uuid UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(church_id,id), FOREIGN KEY(church_id,fund_id) REFERENCES funds(church_id,id), FOREIGN KEY(church_id,cost_center_id) REFERENCES cost_centers(church_id,id), FOREIGN KEY(church_id,reversal_of) REFERENCES journal_entries(church_id,id));
CREATE TABLE journal_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, entry_id uuid NOT NULL, account_id uuid NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents<>0), FOREIGN KEY(church_id,entry_id) REFERENCES journal_entries(church_id,id), FOREIGN KEY(church_id,account_id) REFERENCES accounts(church_id,id));
CREATE TABLE pix_charges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), church_id uuid NOT NULL REFERENCES churches, user_id uuid REFERENCES users, fund_id uuid NOT NULL, txid text NOT NULL UNIQUE, provider text NOT NULL CHECK(provider IN ('demo','efi')), provider_account text NOT NULL, amount_cents bigint NOT NULL CHECK(amount_cents>0), fee_cents bigint NOT NULL DEFAULT 0 CHECK(fee_cents>=0), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','settled','expired','refunded')), copy_paste text NOT NULL DEFAULT '', expires_at timestamptz NOT NULL, entry_id uuid, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(church_id,fund_id) REFERENCES funds(church_id,id), FOREIGN KEY(church_id,entry_id) REFERENCES journal_entries(church_id,id));
CREATE TABLE pix_events(provider text NOT NULL, provider_account text NOT NULL, end_to_end_id text NOT NULL, church_id uuid NOT NULL REFERENCES churches, txid text NOT NULL REFERENCES pix_charges(txid), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(provider,provider_account,end_to_end_id));
CREATE FUNCTION check_entry_balance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*)<2 OR COALESCE(sum(amount_cents),0)<>0 FROM journal_lines WHERE entry_id=NEW.id) THEN RAISE EXCEPTION 'Unbalanced journal'; END IF; RETURN NEW; END $$;
CREATE CONSTRAINT TRIGGER balanced_journal AFTER INSERT ON journal_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_entry_balance();
CREATE FUNCTION check_open_period() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS(SELECT 1 FROM financial_closings WHERE church_id=NEW.church_id AND through_date>=NEW.occurred_on) THEN RAISE EXCEPTION 'Closed financial period'; END IF; RETURN NEW; END $$;
CREATE TRIGGER open_period BEFORE INSERT ON journal_entries FOR EACH ROW EXECUTE FUNCTION check_open_period();
DO $$ DECLARE t text; s text; BEGIN
 FOREACH t IN ARRAY ARRAY['households','people','leadership_terms','credentials','cells','cell_members','meetings','attendance','workflow_cards','accounts','funds','cost_centers','financial_closings','journal_entries','journal_lines'] LOOP
  s:= CASE WHEN t IN ('accounts','funds','cost_centers','financial_closings','journal_entries','journal_lines') THEN 'finance' WHEN t IN ('cells','cell_members','meetings','attendance','workflow_cards') THEN 'cells' ELSE 'people' END;
  EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);
  EXECUTE format('CREATE POLICY read_scope ON %I FOR SELECT USING (church_id=tenant_id() AND can_access(%L,false))',t,s);
  EXECUTE format('CREATE POLICY insert_scope ON %I FOR INSERT WITH CHECK (church_id=tenant_id() AND can_access(%L,true))',t,s);
  IF t NOT IN ('journal_entries','journal_lines','financial_closings') THEN EXECUTE format('CREATE POLICY update_scope ON %I FOR UPDATE USING (church_id=tenant_id() AND can_access(%L,true)) WITH CHECK(church_id=tenant_id() AND can_access(%L,true))',t,s,s); END IF;
 END LOOP;
END $$;
CREATE POLICY own_person ON people FOR SELECT USING(church_id=tenant_id() AND user_id=actor_id());
CREATE POLICY member_funds ON funds FOR SELECT USING(church_id=tenant_id() AND local_role() IS NOT NULL);
ALTER TABLE pix_charges ENABLE ROW LEVEL SECURITY; ALTER TABLE pix_charges FORCE ROW LEVEL SECURITY;
CREATE POLICY charge_read ON pix_charges FOR SELECT USING(church_id=tenant_id() AND (can_access('finance') OR user_id=actor_id()));
CREATE POLICY charge_create ON pix_charges FOR INSERT WITH CHECK(church_id=tenant_id() AND local_role() IS NOT NULL AND user_id=actor_id());
ALTER TABLE pastoral_notes ENABLE ROW LEVEL SECURITY; ALTER TABLE pastoral_notes FORCE ROW LEVEL SECURITY;
CREATE POLICY note_author ON pastoral_notes USING(church_id=tenant_id() AND author_id=actor_id() AND local_role()='admin') WITH CHECK(church_id=tenant_id() AND author_id=actor_id() AND local_role()='admin');
ALTER TABLE schedules ENABLE ROW LEVEL SECURITY; ALTER TABLE schedules FORCE ROW LEVEL SECURITY;
CREATE POLICY schedule_access ON schedules USING(church_id=tenant_id() AND (user_id=actor_id() OR can_access('cells',true))) WITH CHECK(church_id=tenant_id() AND (user_id=actor_id() OR can_access('cells',true)));
ALTER TABLE prayer_requests ENABLE ROW LEVEL SECURITY; ALTER TABLE prayer_requests FORCE ROW LEVEL SECURITY;
CREATE POLICY prayer_author ON prayer_requests USING(church_id=tenant_id() AND (user_id=actor_id() OR local_role()='admin')) WITH CHECK(church_id=tenant_id() AND user_id=actor_id() AND local_role() IS NOT NULL);
ALTER TABLE privacy_requests ENABLE ROW LEVEL SECURITY; ALTER TABLE privacy_requests FORCE ROW LEVEL SECURITY;
CREATE POLICY privacy_author ON privacy_requests USING(church_id=tenant_id() AND (user_id=actor_id() OR local_role()='admin')) WITH CHECK(church_id=tenant_id() AND user_id=actor_id() AND local_role() IS NOT NULL);
GRANT USAGE ON SCHEMA public TO ecclesia_app;
GRANT SELECT,INSERT,UPDATE ON households,people,leadership_terms,credentials,cells,cell_members,meetings,attendance,workflow_cards,schedules,pastoral_notes,prayer_requests,privacy_requests,accounts,funds,cost_centers TO ecclesia_app;
GRANT SELECT,INSERT ON journal_entries,journal_lines,financial_closings,pix_charges TO ecclesia_app;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;
GRANT EXECUTE ON FUNCTION actor_id(),tenant_id(),local_role(),can_access(text,boolean) TO ecclesia_app;
CREATE INDEX people_church ON people(church_id); CREATE INDEX cells_church ON cells(church_id); CREATE INDEX entries_church ON journal_entries(church_id,occurred_on); CREATE INDEX grants_actor ON access_grants(user_id,church_id) WHERE revoked_at IS NULL;
